def cons(num):
    return num > 0 and num % 41 == 0


with open('1704.txt') as f:
    data = list(map(int, f))

min_el = min(num for num in data if cons(num))
answer = []

for x, y in zip(data, data[1:]):
    if x != y and abs(x - y) % min_el == 0:
        answer.append(x + y)

print(len(answer), max(answer))

